"""
End-to-End smoke test for primary VibeSafe user workflows
"""
import unittest
import io
import json
from unittest.mock import patch, MagicMock
import server

class TestEndToEndWorkflow(unittest.TestCase):

    def setUp(self):
        server.app.config['TESTING'] = True
        self.client = server.app.test_client()

    @patch('requests.get')
    def test_complete_devsecops_remediation_pipeline(self, mock_get):
        # Step 1: User uploads a Python file generated by an AI assistant containing vulnerabilities
        raw_code = b'''import os
import sqlite3

API_KEY = "sk_live_99812739182739182739"

def search_account(user_input):
    conn = sqlite3.connect("app.db")
    cursor = conn.cursor()
    cursor.execute(f"SELECT * FROM accounts WHERE name = '{user_input}'")
    os.system("echo 'Auditing: ' + user_input")
    return cursor.fetchall()
'''
        upload_resp = self.client.post(
            '/api/upload',
            data={'file': (io.BytesIO(raw_code), 'ai_generated_service.py')},
            content_type='multipart/form-data'
        )
        self.assertEqual(upload_resp.status_code, 200)
        upload_data = upload_resp.get_json()
        self.assertEqual(upload_data['file_type'], 'python')
        self.assertGreater(len(upload_data['vulns']), 0)

        # Step 2: User runs the autonomous remediation compiler
        remediate_resp = self.client.post(
            '/api/remediate',
            json={'code': upload_data['code'], 'filename': 'ai_generated_service.py'}
        )
        self.assertEqual(remediate_resp.status_code, 200)
        rem_data = remediate_resp.get_json()

        # Step 3: Verify mathematical proof / verification check
        self.assertTrue(rem_data['is_verified'])
        self.assertEqual(len(rem_data['final_vulns']), 0)
        self.assertIn("--- original_source.py", rem_data['diff'])
        self.assertIn("+++ remediated_source.py", rem_data['diff'])

        # Step 4: Verify audit history captured the event without storing raw confidential code
        logs_resp = self.client.get('/api/logs')
        self.assertEqual(logs_resp.status_code, 200)
        logs = logs_resp.get_json()['logs']
        self.assertTrue(any(l['filename'] == 'ai_generated_service.py' for l in logs))

        # Step 5: User audits an AI-generated requirements.txt manifest with a hallucinated package
        mock_resp = MagicMock()
        mock_resp.status_code = 404
        mock_get.return_value = mock_resp

        audit_resp = self.client.post(
            '/api/audit',
            json={'requirements': 'ai-super-lib-hallucinated-xyz\n'}
        )
        self.assertEqual(audit_resp.status_code, 200)
        audit_data = audit_resp.get_json()
        self.assertEqual(audit_data['summary']['flagged_slopsquatted'], 1)
        self.assertEqual(audit_data['results'][0]['risk'], 'CRITICAL')

if __name__ == '__main__':
    unittest.main()
